<template><AdminLayout title="服务总览"><section class="signal"><h2>资料不是库存。<br>它们是 <em>智能服务的依据。</em></h2><p>从上传的原文，到被模型引用的回答，每一份知识都应有清晰的轨迹。</p><div class="signal-track"><span>上传</span><span>解析</span><span>索引</span><span>可检索</span></div></section><section class="stats"><div class="stat"><b>{{ docs.length||'—' }}</b><small>已归档文档</small></div><div class="stat"><b>{{ ready }}</b><small>可检索资料</small></div><div class="stat"><b>{{ active }}</b><small>正在处理</small></div><div class="stat"><b>24小时</b><small>最近同步</small></div></section><section class="split"><article class="sheet"><header class="sheet-head"><div><span>最近归档</span><h2>最近进入资料库</h2></div><RouterLink to="/documents">打开档案 →</RouterLink></header><div v-for="d in docs.slice(0,4)" :key="d.id" class="record"><i class="record-mark">{{d.type}}</i><div><strong>{{d.name}}</strong><small>{{d.size}} · {{d.time}}</small></div><b class="tag" :class="{live:d.status==='ready'}">{{d.status==='ready'?'可检索':'处理中'}}</b></div></article><article class="sheet"><header class="sheet-head"><div><span>下一步操作</span><h2>服务轨道</h2></div></header><div class="flow"><div><b>01</b><span>上传一份 PDF、MD 或 TXT 资料</span></div><div><b>02</b><span>确认解析状态变为可检索</span></div><div><b>03</b><span>在智能对话中验证结果</span></div></div></article></section></AdminLayout></template>
<script setup>import{computed,onMounted,ref}from'vue';import{RouterLink}from'vue-router';import AdminLayout from'../components/layout/AdminLayout.vue';import{fetchDocuments}from'../services/api';const docs=ref([]);const fallback=[{id:'1',name:'产品知识库说明.pdf',type:'PDF',size:'2.4 MB',time:'今天',status:'ready'},{id:'2',name:'客户支持 SOP.md',type:'MD',size:'48 KB',time:'昨天',status:'processing'}];const ready=computed(()=>docs.value.filter(x=>x.status==='ready').length),active=computed(()=>docs.value.filter(x=>x.status!=='ready').length);onMounted(async()=>{try{const d=await fetchDocuments();docs.value=(d.documents||[]).map(x=>({id:x.document_id,name:x.file_name,type:(x.file_type||'txt').toUpperCase(),size:`${Math.ceil((x.file_size||0)/1024)} KB`,time:'最近',status:x.parse_status}))}catch{docs.value=fallback}})</script>
